{"policy":"permit (
    principal is User,
    action == Action::"viewModule",
    resource is Module
)
when {
    principal.roles.containsAny([
        Role::"instructorOfRecord",
        Role::"teachingAssistant",
        Role::"learner",
        Role::"coordinator"
    ])
};

forbid (
    principal is User,
    action == Action::"viewModule",
    resource is Module
)
when {
    !context.fromInstitutionNetwork &&
    (
        context.currentTime < resource.releaseTime ||
        resource.status == ModuleStatus::"draft" ||
        resource.status == ModuleStatus::"scheduled"
    )
};"}
